CREATE PROCEDURE SP_Vue_RptShiftWagesReg   AS 
BEGIN 

DECLARE @sql1 NVARCHAR(MAX);

SET @sql1 = ' ALTER VIEW Vue_RptShiftWagesReg AS SELECT Coycode,Ordid,Finyear,BuyOrdNo,JobNo,EmpName,PartName,WorkComplDet,StyleNo,ProdPcs,ShiftWages,EntryDate,no_of_persons,OrderQty,SUM(CuttingQty) AS CuttingQty,SUM(CumulativeOutput) AS CumulativeOutput,StageID,Sum(CumCost) as CumCost FROM (SELECT DISTINCT Trs_ProdWages.Coycode,OrderMas.OrdId,OrderMas.Finyear, OrderMas.BuyOrdNo, OrderMas.Jobno, Mas_Emp.EmpName, Mas_Part.PartName,Mas_JobWrkComp.WorkComplDet, Trs_ProdWages.StyleNo, Trs_ProdWages.ProdPcs, Trs_ProdWages.ShiftWages, Trs_ProdWages.EntryDate, X.OrderQty, ISNULL(Y.CuttingQty,0)  AS CuttingQty,Trs_ProdWages.no_of_persons, ISNULL(Z.CumulativeOutput,0 ) AS CumulativeOutput,Trs_ProdWages.StageID,IsNull(O.CumCost ,0) as CumCost FROM   (((dbo.Trs_ProdWages Trs_ProdWages INNER JOIN dbo.OrderMas OrderMas ON Trs_ProdWages.Ordid=OrderMas.OrdId) INNER JOIN dbo.Mas_Emp Mas_Emp ON Trs_ProdWages.EmpId=Mas_Emp.ID) INNER JOIN dbo.Mas_Part Mas_Part ON Trs_ProdWages.PartId=Mas_Part.PartID) INNER JOIN dbo.Mas_JobWrkComp Mas_JobWrkComp ON Trs_ProdWages.StageId=Mas_JobWrkComp.Id LEFT JOIN  (SELECT Ordid,Styleno,PartID,SUM(CutPlanQty) AS OrderQty FROM OrderQtyDtl GROUP BY Ordid,Styleno,PartID) AS X ON OrderMas.OrdId = X.OrdID And X.StyleNo = Trs_ProdWages.StyleNo and X.PartID = Trs_ProdWages.PartId LEFT JOIN (SELECT Ordid,StyleNo,PARTID,SUM(ProdPcs) AS CuttingQty FROM Trs_Prodentry INNER JOIN Trs_ProdentryQty ON Trs_Prodentry.id = Trs_ProdentryQty.id  WHERE StageId = 1 GROUP BY OrdId,StyleNo ,PARTID) AS Y ON OrderMas.OrdId = Y.OrdId AND Y.StyleNo = Trs_ProdWages.StyleNo AND Trs_ProdWages.PartId = Y.PARTID  LEFT JOIN (SELECT OrdId,StyleNo,partid,StageID,EmpId,Sum(ProdPcs) AS CumulativeOutput FROM Trs_ProdentryQty INNER JOIN Trs_Prodentry ON Trs_Prodentry.id  = Trs_ProdentryQty.id GROUP BY OrdId,StyleNo,partid,StageID,EmpId) AS Z ON OrderMas.OrdId = Z.OrdId AND Trs_ProdWages.StyleNo = Z.StyleNo AND Trs_ProdWages.StageId = Z.StageID And Trs_ProdWages.PartId = z.PARTID AND Trs_ProdWages.EmpId = Z.EmpId  LEFT JOIN (Select coycode,ordid,styleno,stageID,partid,empid,sum(isnull(shiftwages,0) + IsNull(Addl_Amount,0)) as CumCost From Trs_ProdWages GROUP BY  coycode,ordid,styleno,stageID,partid,empid ) O ON Trs_ProdWages.Coycode = O.Coycode And Trs_ProdWages.Ordid = O.Ordid AND Trs_ProdWages.StyleNo = O.StyleNo AND Trs_ProdWages.StageId = O.StageId AND Trs_ProdWages.PartId = O.PartId AND Trs_ProdWages.EmpId = O.EmpId  UNION  SELECT DISTINCT Trs_ProdWages.Coycode,OrderMas.OrdId,OrderMas.Finyear, OrderMas.BuyOrdNo, OrderMas.Jobno, Mas_Emp.EmpName, Mas_Part.PartName,Mas_JobWrkComp.WorkComplDet, Trs_ProdWages.StyleNo, Trs_ProdWages.ProdPcs, Trs_ProdWages.ShiftWages, Trs_ProdWages.EntryDate, X.OrderQty, ISNULL(Y1.CuttingQty,0)  AS CuttingQty, Trs_ProdWages.no_of_persons, ISNULL(Z1.CumulativeOutput,0 ) AS CumulativeOutput,Trs_ProdWages.StageId,0 as CumCost FROM   (((dbo.Trs_ProdWages Trs_ProdWages INNER JOIN dbo.OrderMas OrderMas ON Trs_ProdWages.Ordid=OrderMas.OrdId) INNER JOIN dbo.Mas_Emp Mas_Emp ON Trs_ProdWages.EmpId=Mas_Emp.ID) INNER JOIN dbo.Mas_Part  Mas_Part ON Trs_ProdWages.PartId=Mas_Part.PartID) INNER JOIN dbo.Mas_JobWrkComp Mas_JobWrkComp ON Trs_ProdWages.StageId=Mas_JobWrkComp.Id  INNER JOIN  (SELECT Ordid,Styleno,PartID,SUM(CutPlanQty) AS OrderQty FROM OrderQtyDtl GROUP BY Ordid,Styleno,PartID) AS X ON OrderMas.OrdId = X.OrdID And X.StyleNo = Trs_ProdWages.StyleNo and X.PartID = Trs_ProdWages.PartId LEFT JOIN  (Select OrdJob,StyleNo,Partid,SUM(RecPcs) AS CuttingQty From Trs_PcsGrn1 INNER JOIN Trs_PcsGrn2 ON Trs_PcsGrn1.ID = Trs_PcsGrn2.ID WHERE   TargetStageID = 1 GROUP BY OrdJob,StyleNo,PARTID) AS Y1 ON OrderMas.OrdId = Y1.OrdJob AND Trs_ProdWages.StyleNo = Y1.StyleNo AND Trs_ProdWages.PARTID = Y1.PARTID LEFT JOIN (Select OrdJob,StyleNo,PARTID,TargetStageID,SUM(RecPcs) AS CumulativeOutput  From Trs_PcsGrn1 INNER JOIN Trs_PcsGrn2 ON Trs_PcsGrn1.ID = Trs_PcsGrn2.ID GROUP BY  OrdJob,StyleNo,PARTID,TargetStageID ) AS Z1  ON OrderMas.OrdId = Z1.OrdJob AND Trs_ProdWages.StyleNo = Z1.StyleNo AND Trs_ProdWages.PartId = Z1.PARTID AND Trs_ProdWages.StageId = Z1.TargetStageID )yyy GROUP BY  Coycode,Ordid,Finyear,BuyOrdNo,JobNo,EmpName,PartName,WorkComplDet,StyleNo,ProdPcs,ShiftWages,EntryDate,no_of_persons,OrderQty,stageid'

EXEC sp_executesql @sql1 

END


-- SP_Vue_RptShiftWagesReg  